with filtered_employees as (select *, cast(is_remote as int) is_remote_flag from employees where manager_id is null), agg as (select case when level in ('L2', 'L4') then 'core' else 'other' end level_group, count(is_remote_flag) is_remote_flag_count from filtered_employees group by case when level in ('L2', 'L4') then 'core' else 'other' end) select level_group, is_remote_flag_count from agg
